<script setup>import{useForm,Link}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';const props=defineProps({service:Object,categories:Array}),s=props.service||{},form=useForm({category_id:s.category_id||'',name:s.name||'',slug:s.slug||'',short_description:s.short_description||'',description:s.description||'',price_from:s.price_from||'',price_label:s.price_label||'',duration:s.duration||'',image:null,image_url:'',status:s.status||'draft',featured:s.featured??false,sort_order:s.sort_order||0,meta_title:s.meta_title||'',meta_description:s.meta_description||''});const submit=()=>s.id?form.patch(`/admin/services/${s.slug}`,{forceFormData:true}):form.post('/admin/services',{forceFormData:true});</script><template><AdminLayout><div class="flex justify-between"><h1 class="section-title">{{s.id?'Edit service':'Add service'}}</h1><Link href="/admin/services" class="btn-light">Back</Link></div><form class="card mt-6 max-w-4xl p-5" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><div class="sm:col-span-2"><label class="label">Name</label><input v-model="form.name" class="input"></div><div><label class="label">Category</label><select v-model="form.category_id" class="input"><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Status</label><select v-model="form.status" class="input"><option value="draft">Draft</option><option value="active">Active</option><option value="archived">Archived</option></select></div><div class="sm:col-span-2"><label class="label">Short description</label><textarea v-model="form.short_description" class="input"></textarea></div><div class="sm:col-span-2"><label class="label">Description</label><textarea v-model="form.description" class="input" rows="8"></textarea></div><div><label class="label">Price from</label><input v-model="form.price_from" type="number" class="input"></div><div><label class="label">Price label</label><input v-model="form.price_label" class="input"></div><div><label class="label">Duration</label><input v-model="form.duration" class="input"></div><div><label class="label">Image</label><input type="file" @change="form.image=$event.target.files[0]"></div><label class="flex gap-2"><input v-model="form.featured" type="checkbox"> Featured</label></div><button class="btn-primary mt-5" :disabled="form.processing">Save service</button></form></AdminLayout></template>
